class Stack:
  def __init__(self):
    self.head = None
    self.tail = None
    self.size = 0
    self.capacity = 10

  def push(self, item):
    if self.size == self.capacity: raise MemoryError
    new_node = Node(item)
    if self.head is None:
      self.head = self.tail = new_node
    else:
      self.tail.next = new_node
      self.tail = new_node
    self.size += 1
  def pop(self):
    if self.size == 0: raise IndexError
    value = self.tail.value
    if self.tail.prev is None:
      self.head = None
    else:
      self.tail.prev.next = None
    self.tail = self.tail.prev
    self.size -= 1
    return value

