def min_window(s, k):
    count = defaultdict(int)
    min_length = float('inf')
    for char in s:
        count[char] += 1
        if len(count) == k and len(min_length) == 0:
            window_start = 0
        else:
            while len(count) > k and s[window_start] in count and window_start < len(s) - 1:
                if count[s[window_start]] == 1 and min_length == float('inf') or window_start + 1 >= len(s):
                    # found a smaller window, update minimum
                    min_length = min(min_length, window_start - window_start + k)
                    while window_start < len(s) - 1:
                        if s[window_start] in count and count[s[window_start]] > 0:
                            window_start += 1
                        else:
                            break
    return s[:min_length]
